function DownloadsPage({ navigate, notify }: { navigate: Navigate; notify: (message: string) => void }) {
  const [query, setQuery] = useState(""); const [category, setCategory] = useState("All"); const [loading, setLoading] = useState<string | null>(null);
  const rows = documentRows.filter((row) => (category === "All" || row.category === category) && row.title.toLowerCase().includes(query.toLowerCase()));
  function download(title: string) { setLoading(title); window.setTimeout(() => { setLoading(null); notify("Document download started."); }, 800); }
  return <><PageHero title="Downloads & documents" text="Find official forms, syllabi, time tables, circulars and student documents." label="Downloads" image={images.diploma} navigate={navigate} /><main className="bg-[#fcfaf7] py-14 md:py-20"><div className="mx-auto max-w-[1160px] px-5 md:px-8"><div className="grid gap-4 border border-stone-200 bg-white p-5 md:grid-cols-[1fr_230px_auto]"><label className="relative"><span className="sr-only">Search documents</span><Search className="absolute left-3 top-3.5 h-4 w-4 text-stone-400" /><input value={query} onChange={(e) => setQuery(e.target.value)} className="h-11 w-full rounded-lg border border-stone-300 pl-10 pr-3 text-sm" placeholder="Search documents" /></label><select value={category} onChange={(e) => setCategory(e.target.value)} className="h-11 rounded-lg border border-stone-300 px-3 text-sm text-stone-600"><option>All</option>{[...new Set(documentRows.map((row) => row.category))].map((item) => <option key={item}>{item}</option>)}</select><Button variant="secondary"><SlidersHorizontal className="h-4 w-4" /> Filters</Button></div><div className="mt-8 overflow-x-auto border-y border-stone-200 bg-white">{rows.length ? <table className="w-full min-w-[760px] text-left"><thead className="bg-[#f9f4ee] text-[11px] uppercase tracking-wider text-stone-500"><tr><th className="px-5 py-4">Document</th><th className="px-5 py-4">Category</th><th className="px-5 py-4">Published</th><th className="px-5 py-4">File</th><th className="px-5 py-4 text-right">Download</th></tr></thead><tbody>{rows.map((row) => <tr key={row.title} className="border-t border-stone-200"><td className="px-5 py-4"><div className="flex items-center gap-3"><span className="grid h-10 w-10 shrink-0 place-items-center bg-red-50 text-red-600"><FileText className="h-5 w-5" /></span><span className="text-sm font-semibold text-[#4a3013]">{row.title}</span></div></td><td className="px-5 py-4 text-sm text-stone-600">{row.category}</td><td className="px-5 py-4 text-sm text-stone-500">{row.date}</td><td className="px-5 py-4 text-xs text-stone-500">{row.type}<br />{row.size}</td><td className="px-5 py-4 text-right"><Button onClick={() => download(row.title)} disabled={loading === row.title} variant="ghost" className="min-h-9 px-2">{loading === row.title ? <LoaderCircle className="h-4 w-4 animate-spin" /> : <Download className="h-4 w-4" />} Download</Button></td></tr>)}</tbody></table> : <div className="py-20 text-center"><FileText className="mx-auto h-10 w-10 text-stone-300" /><h2 className="mt-3 font-semibold text-stone-700">No documents available</h2><p className="mt-1 text-sm text-stone-500">Try a different search or category.</p></div>}</div></div></main></>;
}

