function AdminSettings({ notify }: { notify: (message: string) => void }) {
  return <><AdminHeader title="Website Settings" text="Manage institutional identity, contacts and portal configuration." actions={<Button onClick={() => notify("Website settings saved.")}>Save Changes</Button>} /><div className="grid gap-6 xl:grid-cols-[240px_1fr]"><nav className="h-fit border border-stone-200 bg-white p-2">{["General Information", "Branding", "Contact Details", "Result Settings", "Email Notifications", "Accessibility"].map((item, i) => <button key={item} className={`flex w-full items-center gap-2 rounded-lg px-3 py-2.5 text-left text-xs font-medium ${i === 0 ? "bg-stone-50 text-[#9f682a]" : "text-stone-500 hover:bg-stone-50"}`}>{i === 0 ? <Building2 className="h-4 w-4" /> : <Settings className="h-4 w-4" />}{item}</button>)}</nav><section className="border border-stone-200 bg-white p-5 md:p-7"><h2 className="font-semibold text-stone-900">General Information</h2><p className="mt-1 text-xs text-stone-400">Public organization details shown throughout the website.</p><div className="mt-6 grid gap-5 md:grid-cols-2"><div className="md:col-span-2"><Field label="Organization Name" value="National Academic Board" /></div><div className="md:col-span-2"><Field label="Official Tagline" value="Examination & Certification Authority" /></div><Field label="Public Email" value="help@nab.demo" /><Field label="Helpline Number" value="1800-123-2026" /><SelectField label="Default Language" options={["English", "Hindi"]} /><SelectField label="Timezone" options={["Asia/Kolkata (IST)"]} /></div><div className="mt-7 border-t border-stone-200 pt-6"><h3 className="text-sm font-semibold text-stone-800">Portal Status</h3><div className="mt-4 flex items-center justify-between rounded-lg border border-stone-200 p-4"><div><b className="text-xs text-stone-700">Public website</b><p className="mt-1 text-[11px] text-stone-400">Allow public access to the website and result portal.</p></div><button className="relative h-6 w-11 rounded-full bg-lime-500"><span className="absolute right-1 top-1 h-4 w-4 rounded-full bg-white" /></button></div></div></section></div></>;
}

function renderAdminPage(page: Page, navigate: Navigate, notify: (message: string) => void) {
  switch (page) {
    case "admin-dashboard": return <AdminDashboard navigate={navigate} />;
    case "admin-results": return <AdminResults navigate={navigate} notify={notify} />;
    case "admin-import": return <AdminImport navigate={navigate} notify={notify} />;
    case "admin-students": return <AdminStudents notify={notify} />;
    case "admin-exams": return <AdminExams notify={notify} />;
    case "admin-news": return <AdminEditorial kind="News" notify={notify} />;
    case "admin-notices": return <AdminEditorial kind="Notices" notify={notify} />;
    case "admin-downloads": return <AdminDownloads notify={notify} />;
    default: return <AdminCollection page={page} notify={notify} />;
  }
}

function renderPublicPage(page: Page, navigate: Navigate, notify: (message: string) => void) {
  switch (page) {
    case "about": return <AboutPage navigate={navigate} />;
    case "recognition": return <RecognitionPage navigate={navigate} />;
    case "programmes": return <ProgrammesPage navigate={navigate} />;
    case "programme-details": return <ProgrammeDetailsPage navigate={navigate} />;
    case "examinations": return <ExaminationsPage navigate={navigate} />;
    case "results": return <ResultsPage navigate={navigate} />;
    case "result-detail": return <ResultDetailPage navigate={navigate} notify={notify} />;
    case "verification": return <VerificationPage navigate={navigate} />;
    case "result-archive": return <ResultArchivePage navigate={navigate} />;
    case "news": return <NewsPage navigate={navigate} />;
    case "news-detail": return <NewsDetailPage navigate={navigate} />;
    case "notices": return <NoticesPage navigate={navigate} />;
    case "downloads": return <DownloadsPage navigate={navigate} notify={notify} />;
    case "student-zone": return <StudentZonePage navigate={navigate} />;
    case "services": return <ServicesPage navigate={navigate} notify={notify} />;
    case "gallery": return <GalleryPage navigate={navigate} />;
    case "contact": return <ContactPage navigate={navigate} />;
    default: return <HomePage navigate={navigate} />;
  }
}

const validPages: Page[] = [
  "home", "about", "recognition", "programmes", "programme-details", "examinations", "results", "result-detail", "verification", "result-archive", "news", "news-detail", "notices", "downloads", "student-zone", "services", "gallery", "contact", "admin-dashboard", "admin-results", "admin-import", "admin-students", "admin-exams", "admin-news", "admin-notices", "admin-downloads", "admin-programmes", "admin-gallery", "admin-recognition", "admin-messages", "admin-settings",
];

function pageFromHash(): Page {
  const value = window.location.hash.replace("#", "") as Page;
  return validPages.includes(value) ? value : "home";
}

function AdminLoginPage({ onLogin, navigate }: { onLogin: () => void, navigate: Navigate }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setLoading(true);
    try {
      const res = await fetch("/api/admin-login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username, password })
      });
      if (res.ok) {
        onLogin();
      } else {
        const data = await res.json();
        setError(data.message || "Invalid credentials");
      }
    } catch (err) {
      setError("An error occurred during login");
    } finally {
      setLoading(false);
    }
  };

  return <div className="min-h-screen bg-[#faf5f6] flex flex-col justify-center py-12 sm:px-6 lg:px-8">
    <div className="sm:mx-auto sm:w-full sm:max-w-md text-center">
      <div className="flex justify-center mb-6">
        <Logo compact />
      </div>
      <h2 className="text-center text-3xl font-extrabold text-[#4a3013]">
        Admin Portal
      </h2>
      <p className="mt-2 text-center text-sm text-stone-600">
        Sign in with your credentials to access the dashboard
      </p>
    </div>

    <div className="mt-8 sm:mx-auto sm:w-full sm:max-w-md">
      <div className="bg-white py-8 px-4 shadow sm:rounded-lg sm:px-10 border border-stone-200">
        <form className="space-y-6" onSubmit={handleSubmit}>
          <Field label="Username" required value={username} onChange={setUsername} />
          <Field label="Password" required type="password" value={password} onChange={setPassword} />
          
          {error && <div className="text-red-600 text-sm">{error}</div>}

          <div>
            <Button type="submit" className="w-full" disabled={loading}>
              {loading ? "Signing in..." : "Sign in"}
            </Button>
          </div>
        </form>
        <div className="mt-6 text-center">
           <button onClick={() => navigate("home")} className="text-sm text-stone-500 hover:text-stone-700">Return to home</button>
        </div>
      </div>
    </div>
  </div>;
}

export default function App() {
  const [page, setPage] = useState<Page>(pageFromHash);
  const [adminAuth, setAdminAuth] = useState(false);
  const [toast, setToast] = useState("");

  useEffect(() => {
    const syncPage = () => setPage(pageFromHash());
    window.addEventListener("popstate", syncPage);
    return () => window.removeEventListener("popstate", syncPage);
  }, []);

  useEffect(() => {
    const label = [...adminNav, ...navItems].find((item) => item.page === page)?.label || "Official Portal";
    document.title = `${label} | National Academic Board`;
  }, [page]);

  function navigate(next: Page) {
    if (next !== page) window.history.pushState({}, "", `#${next}`);
    setPage(next);
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function notify(message: string) {
    setToast(message);
    window.setTimeout(() => setToast(""), 3200);
  }

  const isAdmin = page.startsWith("admin-");
  return <>
    {isAdmin ? (adminAuth ? <AdminShell page={page} navigate={navigate} notify={notify} /> : <AdminLoginPage onLogin={() => setAdminAuth(true)} navigate={navigate} />) : <div className="min-h-screen bg-white"><PublicHeader navigate={navigate} active={page} /><AnimatePresence mode="wait"><motion.div key={page} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={{ duration: .2 }}>{renderPublicPage(page, navigate, notify)}</motion.div></AnimatePresence><Footer navigate={navigate} />{page !== "results" && page !== "result-detail" && <button onClick={() => navigate("results")} className="fixed bottom-4 left-4 right-4 z-40 flex h-12 items-center justify-center gap-2 rounded-lg bg-[#ebb81e] text-sm font-bold text-white shadow-xl md:hidden"><Search className="h-4 w-4" /> Check Your Result</button>}</div>}
    <AnimatePresence>{toast && <motion.div role="status" initial={{ opacity: 0, y: 16, x: "-50%" }} animate={{ opacity: 1, y: 0, x: "-50%" }} exit={{ opacity: 0, y: 8, x: "-50%" }} className="fixed bottom-6 left-1/2 z-[120] flex min-w-[280px] items-center gap-3 rounded-lg bg-[#4a3013] px-4 py-3 text-sm font-medium text-white shadow-2xl"><CheckCircle2 className="h-5 w-5 text-lime-400" />{toast}</motion.div>}</AnimatePresence>
  </>;
}